package com.fuelflex.platform.sale.controller;
import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.fuelflex.platform.operations.dto.OperationalDtos.PosOperationalContext; import com.fuelflex.platform.operations.service.PumpAttendantOperationalContextService; import com.fuelflex.platform.sale.dto.PosSaleDtos.*; import com.fuelflex.platform.sale.service.PosFuelSaleService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/api/v1/pump-attendant/pos") @RequiredArgsConstructor @PreAuthorize("hasAuthority('PUMP_ATTENDANT')") public class PumpAttendantPosController{private final PumpAttendantOperationalContextService contextService;private final PosFuelSaleService sales;
 @GetMapping("/context")@PreAuthorize("hasAuthority('pos-sale:view')")public PosOperationalContext context(){return contextService.requireCurrentContext();}
 @PostMapping("/sales")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('pos-sale:create')")public SaleResponse create(@Valid @RequestBody CreateSaleRequest r){return sales.create(r);}
 @PostMapping("/sales/credit")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('pos-credit-sale:create')")public SaleResponse credit(@Valid @RequestBody CreateCreditSaleRequest r){return sales.createCredit(r);}
 @GetMapping("/sales")@PreAuthorize("hasAuthority('pos-sale:view')")public List<SaleResponse> all(){return sales.findCurrentOperationalDaySales();}
 @GetMapping("/sales/{id}")@PreAuthorize("hasAuthority('pos-sale:view')")public SaleResponse one(@PathVariable UUID id){return sales.findById(id);}}
